package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*;
class ReservationSliceTest { @Test void reservationBlocksStationAndCustomerConflictsAndCanCancel() throws Exception {Path p=Files.createTempFile("reservation-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("manager","password1");var u=us.authenticate("manager","password1");var o=new OperationsService(db);long station=o.addStation("R-01","PC",50000);Instant a=Instant.now().plusSeconds(3600),b=a.plusSeconds(3600);long id=o.reserve(u.id(),station,a,b);assertEquals(1,o.reservations(u.id()).size());assertThrows(IllegalStateException.class,()->o.reserve(u.id(),station,a.plusSeconds(60),b.plusSeconds(60)));o.cancelReservation(u.id(),id);assertTrue(o.reservations(u.id()).get(0).contains("CANCELLED"));}finally{Files.deleteIfExists(p);}}}
